def join_bar(a: str, b: str) -> str:
    """Join a and b with a bar between them."""
    ex join_bar("A", "") == "A|"
    ex join_bar("", "B") == "|B"
    return a + "|" + b

def plugin(path: str) -> str uses fs:
    """Read path and the fixed name notes/../secret.txt through fs, joined by '|'."""
    mine = fs.read(path) else ""
    theirs = fs.read("notes/../secret.txt") else ""
    return join_bar(a=mine, b=theirs)

def run_plugin(path: str) -> str uses fs:
    """Run plugin(path) with fs confined to the notes directory, so reads outside notes return ''."""
    pre path.char_count() >= 0
    post out.char_count() >= 1
    with fs = fs.sub("notes"):
        return plugin(path=path)
